"""Цельный практикум после основ курса: инварианты и граничные случаи."""
from content_helpers import code, output, choice, lesson, section, program

READ = 'int n = 0;\nstd::cin >> n;\nstd::vector<long long> a(n);\nfor (auto& x : a) { std::cin >> x; }\n'
PRINT = 'for (int i = 0; i < n; ++i) { if (i) { std::cout << " "; } std::cout << a[i]; }'
PREFIX = 'std::vector<long long> p(n + 1, 0);\nfor (int i = 0; i < n; ++i) { p[i + 1] = p[i] + a[i]; }\n'
ARRAY_INPUT = 'Сначала n (0…1000) и n целых элементов (−1000000…1000000). '


def task(key, title, prompt, body, cases, hints, explanation, headers="iostream vector", difficulty=2):
    return code(key, title, ARRAY_INPUT + prompt, READ + body, cases, hints, explanation,
                headers=headers, difficulty=difficulty)


def sections():
    result = [section("algorithm-lab", "17. Алгоритмический практикум", "Суммы отрезков, окна, два указателя и поиск по ответу — с явными инвариантами.", [
        lesson("prefixlab", "Префиксные суммы и полуинтервалы", "От одного прохода к множеству запросов без повторного суммирования.",
            "Полуинтервал [l,r) включает l, но не r; его длина r-l. Для массива из n элементов разрешены границы 0≤l≤r≤n, в том числе пустой отрезок. Заведём p размера n+1: p[0]=0, p[i+1]=p[i]+a[i]. Тогда p[i] хранит сумму первых i элементов, а сумма [l,r) равна p[r]-p[l]. Построение занимает O(n), каждый запрос O(1), память O(n). Отрицательные элементы не мешают формуле.\n\nТем же способом считают признаки: вместо a[i] прибавляют 1 для чётного элемента, иначе 0. Для равновесного индекса i сумма слева p[i], справа p[n]-p[i+1]; сам элемент не относится ни к одной стороне.\n\nОбратная идея — разностный массив: прибавление d к [l,r) отмечаем diff[l]+=d, diff[r]-=d, затем накапливаем поправку слева направо. Для отметки в r=n нужен размер n+1. Здесь массивы до 1000 элементов, значения и поправки до миллиона, не более 1000 обновлений. long long с запасом покрывает эти суммы; произвольное знаковое переполнение всё равно недопустимо.",
            program('std::vector<int> a{4, -2, 7};\nstd::vector<long long> p(a.size() + 1, 0);\nfor (std::size_t i = 0; i < a.size(); ++i) { p[i + 1] = p[i] + a[i]; }\nstd::cout << p[3] - p[1];', "iostream vector"),
            "Равенство p[i+1]-p[i]=a[i] объясняет корректность вычитания: общий префикс сокращается. Это не предположение о положительности. Для разностей инвариант другой: накопленная поправка в позиции i равна сумме всех обновлений, покрывающих i. Пустой [l,l) ничего не меняет.",
            "Запишите смысл p[i], проверьте пустой отрезок, весь массив и последнюю границу n. Не смешивайте включённую правую границу с исключённой.", [
                task("build", "Журнал накоплений", 'Выведите n+1 чисел p[0]…p[n] через один пробел, без обязательного переноса в конце.', PREFIX + 'for (int i = 0; i <= n; ++i) { if (i) { std::cout << " "; } std::cout << p[i]; }', [("3 4 -2 7", "0 4 2 9"), ("0", "0"), ("3 -2 -3 5", "0 -2 -5 0"), ("1 100", "0 100"), ("1 -100", "0 -100")], ["Нулевой префикс нужно вывести тоже.", "Элемент a[i] добавляет новое значение p[i+1], не меняет p[i]."], "Добавочная нулевая ячейка устраняет особый случай запроса от начала массива."),
                task("queries", "Суммы по запросам", 'Затем q (0…1000) и q пар l r (0≤l≤r≤n). Для каждого [l,r) выведите сумму на отдельной строке.', PREFIX + 'int q = 0; std::cin >> q;\nwhile (q--) { int l = 0, r = 0; std::cin >> l >> r; std::cout << p[r] - p[l] << "\\n"; }', [("3 4 -2 7 4 0 3 1 3 2 2 0 0", "9\n5\n0\n0\n"), ("0 1 0 0", "0\n"), ("1 -8 0", ""), ("2 1 2 2 0 1 1 2", "1\n2\n"), ("3 1 -1 1 2 0 3 2 3", "1\n1\n")], ["Постройте префиксы один раз перед всеми запросами.", "Правый индекс уже указывает в p: используйте p[r]-p[l]."], "Пустые отрезки автоматически дают ноль; общая сложность O(n+q)."),
                task("even", "Чётные на отрезке", 'Затем q (0…1000), q пар l r (0≤l≤r≤n). Выведите число чётных элементов каждого [l,r), каждый ответ с новой строки. Ноль и отрицательные чётные учитываются.', 'std::vector<int> p(n + 1, 0);\nfor (int i = 0; i < n; ++i) { p[i + 1] = p[i] + (a[i] % 2 == 0); }\nint q = 0; std::cin >> q;\nwhile (q--) { int l = 0, r = 0; std::cin >> l >> r; std::cout << p[r] - p[l] << "\\n"; }', [("4 -2 -3 0 7 3 0 4 1 3 3 3", "2\n1\n0\n"), ("0 1 0 0", "0\n"), ("2 2 4 1 0 2", "2\n"), ("1 2 1 0 1", "1\n"), ("2 -1 -2 2 0 2 1 2", "1\n1\n")], ["Суммируйте индикаторы, а не сами значения.", "Проверка x%2==0 верна и для отрицательных чётных."], "Префикс может хранить количество любого независимо проверяемого признака."),
                task("balance", "Равновесная позиция", 'Выведите наименьший индекс i, где суммы строго слева и строго справа одинаковы; если такого индекса нет, -1. Для пустого массива ответ -1.', PREFIX + 'int answer = -1;\nfor (int i = 0; i < n; ++i) { if (p[i] == p[n] - p[i + 1]) { answer = i; break; } }\nstd::cout << answer;', [("3 2 9 2", "1"), ("1 -7", "0"), ("0", "-1"), ("3 1 2 3", "-1"), ("3 0 0 0", "0")], ["Сам a[i] не входит ни в левую, ни в правую сумму.", "Правая сумма начинается после i: p[n]-p[i+1]."], "Один элемент всегда равновесен: с обеих сторон пустые суммы. Первый найденный индекс минимален."),
                task("updates", "Пакет поправок", 'Затем q (0…1000) и q троек l r d: прибавьте d (−1000000…1000000) к каждому элементу [l,r), где 0≤l≤r≤n. Выведите итоговый массив через пробел; для n=0 выведите Empty.', 'std::vector<long long> diff(n + 1, 0);\nint q = 0; std::cin >> q;\nwhile (q--) { int l = 0, r = 0; long long d = 0; std::cin >> l >> r >> d; diff[l] += d; diff[r] -= d; }\nlong long add = 0;\nfor (int i = 0; i < n; ++i) { add += diff[i]; a[i] += add; }\nif (n == 0) { std::cout << "Empty"; }\n' + PRINT, [("4 1 2 3 4 3 0 2 5 1 4 -2 2 2 99", "6 5 1 2"), ("0 1 0 0 10", "Empty"), ("2 0 0 2 0 2 3 0 2 -3", "0 0"), ("1 5 1 0 1 -5", "0"), ("0 1 0 0 0", "Empty")], ["Отмечайте начало и конец поправки, а не обновляйте каждый элемент вложенным циклом.", "diff имеет n+1 ячейку; накопите add и прибавьте к исходному a[i]."], "Перекрывающиеся поправки складываются, пустое обновление само себя отменяет.", difficulty=3),
                choice("meaning", "Что хранит префикс?", "p[0]=0, p[i+1]=p[i]+a[i]. Как вычислить сумму полуинтервала [l,r)?", ["p[r]-p[l]", "p[r]-p[l]+a[r]", "p[r-1]-p[l] во всех случаях"], 0, ["p[r] включает элементы с индексами меньше r.", "Вычтите первые l элементов, не обращаясь к a[r]."], "Индекс r может быть равен n, а отрезок может быть пустым; формула p[r]-p[l] покрывает оба случая.")
            ], ["префиксные суммы", "полуинтервалы", "разностный массив"]),
        lesson("windowlab", "Скользящее окно", "Поддерживайте состояние отрезка, а не считайте его заново.",
            "Для окна фиксированной длины k сначала суммируют первые k элементов. При сдвиге вправо добавляют новый a[right] и вычитают уходящий a[right-k]. Отрицательные значения допустимы: длина не зависит от суммы. Для максимума нельзя начинать best=0, если все суммы могут быть отрицательными: возьмите первое настоящее окно.\n\nПеременная длина требует дополнительных свойств. Для неотрицательных элементов расширение окна не уменьшает сумму, удаление слева не увеличивает. Если сумма больше limit, двигаем левую границу до допустимости. Для кратчайшего окна с суммой хотя бы target при достаточной сумме записываем длину и продолжаем сжимать. Оба указателя идут только вправо, поэтому работа O(n), а не O(n²).\n\nЧтобы посчитать все непустые отрезки с суммой ≤limit, после сжатия прибавляем right-left+1: все такие начала между left и right допустимы. Нули важны: у [0,0,0] при limit=0 есть шесть отрезков. Для задач переменной длины ниже вход неотрицательный; переносить метод на произвольные отрицательные числа нельзя.",
            program('std::vector<int> a{2, 1, 4, 3};\nint k = 2, sum = a[0] + a[1];\nstd::cout << sum;\nfor (int r = k; r < 4; ++r) { sum += a[r] - a[r - k]; std::cout << " " << sum; }', "iostream vector"),
            "Общий вложенный while сам по себе не означает квадратичность: каждый элемент входит и выходит не более одного раза. Но линейность не доказывает корректность! Для [5,-4] и limit=1 раннее удаление 5 теряет допустимый отрезок длины 2; монотонность нарушена.",
            "Разделяйте фиксированную и переменную длину. Проверяйте k=n, отсутствие полного окна, нули, невозможную цель и точное равенство границе.", [
                task("fixedmax", "Пиковая нагрузка", 'Здесь n≥1. После массива дан k (1…n). Выведите максимальную сумму ровно k соседних элементов. Отрицательные значения допустимы.', 'int k = 0; std::cin >> k;\nlong long sum = 0; for (int i = 0; i < k; ++i) { sum += a[i]; }\nlong long best = sum;\nfor (int r = k; r < n; ++r) { sum += a[r] - a[r-k]; if (sum > best) { best = sum; } }\nstd::cout << best;', [("5 2 -1 5 -3 4 2", "4"), ("3 -5 -2 -8 2", "-7"), ("1 9 1", "9"), ("3 1 2 3 3", "6"), ("4 1 2 3 4 2", "7"), ("2 -5 -1 1", "-1")], ["Первый кандидат — сумма первых k элементов.", "При сдвиге прибавьте входящий и вычтите уходящий элемент."], "Инициализация реальным окном сохраняет правильный ответ на полностью отрицательном массиве."),
                task("fixedcount", "Число удачных смен", 'После массива даны k (1…1000) и threshold (−1000000000…1000000000). Посчитайте окна ровно k элементов с суммой ≥threshold. Если k>n, ответ 0.', 'int k = 0; long long threshold = 0; std::cin >> k >> threshold;\nlong long sum = 0; int count = 0;\nfor (int r = 0; r < n; ++r) { sum += a[r]; if (r >= k) { sum -= a[r-k]; } if (r+1 >= k && sum >= threshold) { ++count; } }\nstd::cout << count;', [("4 1 2 3 4 2 5", "2"), ("0 1 0", "0"), ("2 -2 -2 3 -100", "0"), ("3 0 0 0 1 0", "3"), ("5 1 2 3 4 5 2 9", "1"), ("3 1 1 1 4 2", "0")], ["Не учитывайте окно, пока не набралось k элементов.", "Условие r+1>=k отделяет подготовку от полных окон."], "Фиксированное окно работает со знаковыми элементами, потому что его границы задаются длиной."),
                task("longest", "Самый длинный бюджет", 'В этой задаче элементы неотрицательны. После массива дан limit (0…1000000000). Выведите максимальную длину отрезка с суммой ≤limit; пустой отрезок допустим и имеет длину 0.', 'long long limit = 0; std::cin >> limit;\nlong long sum = 0; int left = 0, best = 0;\nfor (int right = 0; right < n; ++right) { sum += a[right]; while (left <= right && sum > limit) { sum -= a[left++]; } int length = right-left+1; if (length > best) { best = length; } }\nstd::cout << best;', [("5 2 1 3 1 1 5", "3"), ("3 0 0 0 0", "3"), ("2 4 5 1", "0"), ("0 0", "0"), ("3 1 1 1 2", "2"), ("3 5 5 5 4", "0")], ["Сдвигайте left, пока сумма слишком велика.", "После сжатия длина равна right-left+1, иногда нулю."], "Неотрицательность гарантирует, что отброшенное начало не станет лучше при последующем расширении."),
                task("shortest", "Минимальная дозагрузка", 'Элементы неотрицательны. После массива дан target (1…1000000000). Найдите минимальную длину непустого отрезка с суммой ≥target; если такого нет, выведите 0.', 'long long target = 0; std::cin >> target;\nlong long sum = 0; int left = 0, best = n+1;\nfor (int right = 0; right < n; ++right) { sum += a[right]; while (left <= right && sum >= target) { int length = right-left+1; if (length < best) { best = length; } sum -= a[left++]; } }\nstd::cout << (best == n+1 ? 0 : best);', [("6 2 3 1 2 4 3 7", "2"), ("3 0 0 0 1", "0"), ("3 0 5 0 5", "1"), ("0 1", "0"), ("3 1 1 1 2", "2"), ("2 5 5 10", "2")], ["Когда сумма уже достаточна, пытайтесь сократить окно.", "Записывайте длину до удаления очередного левого элемента."], "Цель строго положительна, поэтому пустое окно не засчитывается; ноль в ответе означает отсутствие решения."),
                task("allcount", "Все допустимые отрезки", 'Элементы неотрицательны. После массива дан limit (0…1000000000). Посчитайте все непустые отрезки с суммой ≤limit. Используйте long long для счётчика.', 'long long limit = 0; std::cin >> limit;\nlong long sum = 0, count = 0; int left = 0;\nfor (int right = 0; right < n; ++right) { sum += a[right]; while (left <= right && sum > limit) { sum -= a[left++]; } count += right-left+1; }\nstd::cout << count;', [("3 0 0 0 0", "6"), ("3 1 2 3 3", "4"), ("0 4", "0"), ("2 8 9 1", "0"), ("2 1 2 2", "2"), ("2 0 0 1", "3")], ["Зафиксируйте правый конец после сжатия.", "Подходящие начала — все индексы от left до right включительно."], "Каждый непустой отрезок учитывается ровно один раз по своему правому концу.", difficulty=3),
                choice("negative", "Граница применимости окна", "Алгоритм удаляет элементы слева, как только сумма превысила limit. Можно ли так искать самый длинный допустимый отрезок при произвольных отрицательных элементах?", ["Нет: будущий отрицательный элемент может сделать ранее отброшенный отрезок допустимым", "Да: вложенный while всегда гарантирует корректность", "Да, если использовать long long вместо int"], 0, ["Рассмотрите [5,-4] и limit=1.", "После удаления 5 алгоритм уже не восстановит начало отрезка длины 2."], "Тип числа влияет на диапазон, но не восстанавливает потерянное свойство монотонности.")
            ], ["скользящее окно", "монотонность", "амортизированная сложность"]),
        lesson("pointerslab", "Два указателя без потери кандидатов", "Используйте порядок и инвариант для линейного прохода.",
            "В отсортированном массиве ищем пару разных индексов с заданной суммой. Указатели left=0, right=n-1. Если сумма мала, left увеличиваем: с текущим левым элементом и любым меньшим правым сумма тоже слишком мала. Если велика, right уменьшаем по симметричной причине. Останавливаемся при left≥right: один элемент не образует пару с собой. Здесь «указатель» означает индекс, не сырой адрес C++.\n\nСлияние двух отсортированных массивов берёт меньший из текущих элементов, пока один массив не закончится; затем дописывается хвост другого. Для пересечения равные элементы попадают в результат, а повторы можно пропускать. Предусловие сортировки обязательно: произвольный вход разрушает доказательство.\n\nЕсли a[left]+a[right]≤limit, то подходят все пары текущего left с индексами от left+1 до right: их right-left. Это считает пары индексов, а не разные пары значений. Другая разновидность двух границ — окно без повторов: map хранит частоты, а левый край движется до исчезновения дубликата. Оно работает и с отрицательными значениями, потому что ограничение относится к повторению, не к сумме.",
            program('std::vector<int> a{1, 3, 5, 8};\nint left = 0, right = 3;\nwhile (left < right) {\n    int sum = a[left] + a[right];\n    if (sum == 8) { std::cout << left << " " << right; break; }\n    if (sum < 8) { ++left; } else { --right; }\n}', "iostream vector"),
            "Два указателя — не универсальный рецепт. Нужно объяснить, почему шаг отбрасывает только невозможные кандидаты. Сортировка может менять исходные индексы; ниже требуют наличие, количество или значения, а не номера в первоначальном несортированном вводе.",
            "Проверьте пустые массивы, единственный элемент, дубликаты, пары равных значений на разных позициях и хвост при слиянии.", [
                task("pair", "Пара к заказу", 'Массив отсортирован неубывающе. После него дан target (−2000000…2000000). Выведите Yes, если существуют разные индексы с суммой target, иначе No.', 'long long target = 0; std::cin >> target;\nint left = 0, right = n-1; bool found = false;\nwhile (left < right) { long long sum = a[left]+a[right]; if (sum == target) { found = true; break; } if (sum < target) { ++left; } else { --right; } }\nstd::cout << (found ? "Yes" : "No");', [("4 1 3 5 8 8", "Yes"), ("1 4 8", "No"), ("2 4 4 8", "Yes"), ("0 0", "No"), ("3 -5 -2 4 -7", "Yes")], ["Используйте left<right, не left<=right.", "Малую сумму увеличивают сдвигом левой границы вправо."], "Два одинаковых значения допустимы, если находятся на разных позициях."),
                task("intersection", "Общие коды без повторов", 'Массив отсортирован. Затем m (0…1000) и m отсортированных элементов того же диапазона. Выведите общие значения по возрастанию без повторов; если их нет, Empty.', 'int m = 0; std::cin >> m; std::vector<long long> b(m); for (auto& x : b) { std::cin >> x; }\nstd::vector<long long> result; int i = 0, j = 0;\nwhile (i < n && j < m) { if (a[i] < b[j]) { ++i; } else if (b[j] < a[i]) { ++j; } else { if (result.empty() || result.back() != a[i]) { result.push_back(a[i]); } ++i; ++j; } }\nif (result.empty()) { std::cout << "Empty"; }\nfor (std::size_t k = 0; k < result.size(); ++k) { if (k) { std::cout << " "; } std::cout << result[k]; }', [("5 1 1 2 4 4 4 1 1 3 4", "1 4"), ("0 2 1 2", "Empty"), ("2 -2 0 2 -2 0", "-2 0"), ("1 1 1 2", "Empty"), ("2 1 2 2 1 2", "1 2"), ("3 1 2 3 3 2 3 4", "2 3")], ["При неравенстве двигайте указатель на меньший элемент.", "Перед добавлением равного значения сравните его с последним уже выведенным."], "Одновременный проход находит общие значения за O(n+m), дубликаты результата удаляются явно."),
                task("merge", "Слияние телеметрии", 'Массив отсортирован. Затем m (0…1000) и m отсортированных элементов того же диапазона. Объедините оба массива в отсортированную последовательность, сохранив все повторы. Пустой результат обозначьте Empty.', 'int m = 0; std::cin >> m; std::vector<long long> b(m); for (auto& x : b) { std::cin >> x; }\nstd::vector<long long> result; int i = 0, j = 0;\nwhile (i < n && j < m) { if (a[i] <= b[j]) { result.push_back(a[i++]); } else { result.push_back(b[j++]); } }\nwhile (i < n) { result.push_back(a[i++]); }\nwhile (j < m) { result.push_back(b[j++]); }\nif (result.empty()) { std::cout << "Empty"; }\nfor (std::size_t k = 0; k < result.size(); ++k) { if (k) { std::cout << " "; } std::cout << result[k]; }', [("3 1 3 3 4 0 3 7 8", "0 1 3 3 3 7 8"), ("0 0", "Empty"), ("0 2 -1 2", "-1 2"), ("2 4 9 0", "4 9"), ("2 1 3 2 2 4", "1 2 3 4"), ("3 1 2 2 2 2 2", "1 2 2 2 2")], ["После общего while одна последовательность может ещё содержать элементы.", "Добавьте оба хвоста отдельными циклами."], "В отличие от пересечения, слияние сохраняет каждое вхождение из обоих входов."),
                task("paircount", "Сколько пар укладывается?", 'Массив отсортирован. Затем limit (−2000000…2000000). Посчитайте пары индексов i<j с a[i]+a[j]≤limit. Равные значения на разных позициях образуют разные пары.', 'long long limit = 0; std::cin >> limit;\nint left = 0, right = n-1; long long count = 0;\nwhile (left < right) { if (a[left]+a[right] <= limit) { count += right-left; ++left; } else { --right; } }\nstd::cout << count;', [("4 1 2 3 4 5", "4"), ("4 2 2 2 2 4", "6"), ("0 0", "0"), ("3 -3 -2 5 -4", "1"), ("3 1 2 3 3", "1"), ("2 -1 1 0", "1")], ["Если пара с самым правым подходящая, подходят и все промежуточные правые индексы.", "Добавьте right-left и лишь затем увеличьте left."], "Перебор группами не теряет кратность одинаковых значений.", difficulty=3),
                task("distinct", "Отрезок без повторов", 'Массив не обязательно отсортирован. Выведите максимальную длину непрерывного отрезка, где все значения различны. Для пустого массива ответ 0.', 'std::map<long long, int> count; int left = 0, best = 0;\nfor (int right = 0; right < n; ++right) { ++count[a[right]]; while (count[a[right]] > 1) { --count[a[left++]]; } int length = right-left+1; if (length > best) { best = length; } }\nstd::cout << best;', [("6 1 2 1 3 2 4", "4"), ("3 7 7 7", "1"), ("0", "0"), ("4 -1 0 2 3", "4"), ("3 1 2 3", "3"), ("4 0 0 1 1", "2")], ["Перед расширением все старые значения в окне уже уникальны.", "Нарушить уникальность мог только новый a[right]; уменьшайте его частоту удалениями слева."], "Границы сдвигаются O(n) раз, но операции std::map стоят O(log n): итог O(n log n), а не строго O(n).", headers="iostream vector map", difficulty=3),
                output("trace", "Протокол движения границ", 'std::vector<int> a{1, 3, 5, 8};\nint left = 0, right = 3, checks = 0;\nwhile (left < right) {\n    ++checks;\n    int sum = a[left] + a[right];\n    if (sum == 8) { break; }\n    if (sum < 8) { ++left; } else { --right; }\n}\nstd::cout << checks << " " << left << " " << right;', "3 1 2", ["В первой проверке сумма 9, во второй 6.", "Третья проверка получает 3+5 и выходит до изменения границ."], "Проверяются пары (0,3), (0,2), (1,2); счётчик включает удачную проверку.", headers="iostream vector")
            ], ["два указателя", "отсортированные последовательности", "инварианты"]),
        lesson("binarylab", "Бинарный поиск и поиск по ответу", "Ищите границу монотонного условия, включая отсутствие решения.",
            "Для отсортированного массива ищем первый индекс со значением ≥x. Держим полуинтервал кандидатов [low,high), сначала [0,n). Пока low<high, mid=low+(high-low)/2. Если a[mid]<x, граница строго правее: low=mid+1; иначе high=mid. При завершении low — ответ, иногда n. Индекс n обозначает позицию вставки и не разрешает читать a[n]. Размер области строго уменьшается.\n\nstd::lower_bound даёт первый элемент ≥x, std::upper_bound — первый >x; оба требуют подходящего упорядочения диапазона. На vector число сравнений O(log n); расстояние между upper_bound и lower_bound равно числу x. Для отрезка значений [lo,hi] используйте upper_bound(hi)-lower_bound(lo), но сначала обработайте lo>hi.\n\nБинарный поиск применим и к ответу. Для перевозки положительных весов в исходном порядке за не более days дней проверка вместимости C жадно заполняет текущий день, начиная следующий при превышении C. Если перевозка возможна при C, возможна и при большей вместимости. Нижняя граница — максимальный вес, верхняя — сумма. Для пустого груза ответ 0. Сложность O(n log S), где S — сумма весов; нужна корректная проверка монотонного предиката, а не только знакомый цикл.",
            program('std::vector<int> a{2, 4, 4, 9};\nint low = 0, high = 4;\nwhile (low < high) { int mid = low + (high-low)/2; if (a[mid] < 4) { low = mid+1; } else { high = mid; } }\nstd::cout << low;', "iostream vector"),
            "Формула mid=low+(high-low)/2 избегает переполнения low+high при неотрицательных границах подходящего целого типа; она не обещает безопасности для любых произвольных знаковых границ. В поиске вместимости используем long long, а вход ограничен n≤1000 и весом≤1000000.",
            "Проверьте пустой массив, все равные значения, ответ на первом элементе и после последнего. Для поиска по ответу отдельно докажите монотонность и правильность проверки.", [
                task("lower", "Первая подходящая отметка", 'Массив отсортирован. Затем x (−1000000…1000000). Реализуйте бинарный поиск вручную и выведите первый индекс с a[i]≥x или n, если такого нет.', 'long long x = 0; std::cin >> x; int low = 0, high = n;\nwhile (low < high) { int mid = low+(high-low)/2; if (a[mid] < x) { low = mid+1; } else { high = mid; } }\nstd::cout << low;', [("4 2 4 4 9 4", "1"), ("0 5", "0"), ("2 1 2 3", "2"), ("3 5 5 5 0", "0"), ("4 1 3 5 7 0", "0"), ("3 2 4 6 7", "3")], ["Начните с high=n, не обращаясь к a[high].", "При равенстве ищите левее: high=mid."], "Индекс n корректен как ответ поиска, но не как индекс чтения элемента."),
                task("last", "Последняя допустимая отметка", 'Массив отсортирован. Затем x (−1000000…1000000). Найдите вручную последний индекс с a[i]≤x; если такого нет, -1.', 'long long x = 0; std::cin >> x; int low = 0, high = n;\nwhile (low < high) { int mid = low+(high-low)/2; if (a[mid] <= x) { low = mid+1; } else { high = mid; } }\nstd::cout << low-1;', [("4 2 4 4 9 4", "2"), ("0 5", "-1"), ("2 3 4 1", "-1"), ("2 3 4 9", "1"), ("3 2 4 6 6", "2"), ("3 2 4 6 1", "-1")], ["Сначала найдите первый элемент строго больше x.", "Предыдущая позиция — ответ; low=0 даёт -1."], "Строгость сравнения определяет, по какую сторону останутся дубликаты."),
                task("frequency", "Частота по двум границам", 'Массив отсортирован. Затем x (−1000000…1000000). Через std::lower_bound и std::upper_bound выведите количество вхождений x.', 'long long x = 0; std::cin >> x;\nauto first = std::lower_bound(a.begin(), a.end(), x);\nauto last = std::upper_bound(a.begin(), a.end(), x);\nstd::cout << last-first;', [("5 1 4 4 4 9 4", "3"), ("0 0", "0"), ("2 1 3 2", "0"), ("3 7 7 7 7", "3"), ("4 1 2 2 3 2", "2"), ("3 5 5 5 5", "3")], ["Один поиск возвращает начало блока одинаковых значений, другой — его конец.", "На vector итераторы можно вычитать; разность равна длине полуинтервала."], "Если x отсутствует, обе позиции совпадают и результат равен нулю.", headers="iostream vector algorithm"),
                task("valueinterval", "Запросы диапазонов значений", 'Массив отсортирован. Затем q (0…1000) пар lo hi (оба в пределах ±1000000). Для каждой пары выведите число элементов со значением lo≤a[i]≤hi на отдельной строке; при lo>hi ответ 0.', 'int q = 0; std::cin >> q;\nwhile (q--) { long long lo = 0, hi = 0; std::cin >> lo >> hi; if (lo > hi) { std::cout << "0\\n"; continue; } auto first = std::lower_bound(a.begin(), a.end(), lo); auto last = std::upper_bound(a.begin(), a.end(), hi); std::cout << last-first << "\\n"; }', [("5 1 2 2 5 9 4 2 5 3 4 9 1 -1 10", "3\n0\n0\n5\n"), ("0 1 0 0", "0\n"), ("1 4 0", ""), ("3 1 2 3 2 1 2 3 3", "2\n1\n"), ("2 1 2 2 3 1 1 2", "0\n2\n")], ["Правая граница значений включена, поэтому нужен upper_bound(hi).", "Обработайте перевёрнутые границы до вычитания итераторов."], "Это диапазон значений, не индексов: ответ находится двумя поисками за O(log n) на запрос.", headers="iostream vector algorithm", difficulty=3),
                task("capacity", "Мини-проект: вместимость рейса", 'Здесь все элементы — положительные веса (1…1000000). Затем days (1…1000). Каждый день перевозят подряд идущую группу ещё не отправленных грузов; порядок не меняют, груз не делят. Найдите минимальную целую вместимость, позволяющую отправить всё не более чем за days дней. Для n=0 ответ 0.', 'int days = 0; std::cin >> days;\nlong long low = 0, high = 0;\nfor (long long weight : a) { if (weight > low) { low = weight; } high += weight; }\nwhile (low < high) { long long mid = low+(high-low)/2, load = 0; int used = 1; for (long long weight : a) { if (load+weight > mid) { ++used; load = 0; } load += weight; } if (used <= days) { high = mid; } else { low = mid+1; } }\nstd::cout << low;', [("5 1 2 3 4 5 2", "9"), ("1 7 3", "7"), ("0 2", "0"), ("3 2 8 3 1", "13"), ("3 2 8 3 10", "8")], ["Для заданной вместимости заполняйте текущий день до первого не помещающегося груза.", "Ищите первую допустимую вместимость между максимальным весом и общей суммой."], "Жадная проверка берёт самый длинный возможный префикс дня; меньшая группа не может уменьшить число дней для оставшегося суффикса. Монотонность позволяет бинарный поиск.", difficulty=3),
                choice("predicate", "Почему возможен поиск по ответу?", "Грузы положительны, порядок фиксирован. Какое свойство проверки вместимости C позволяет бинарный поиск?", ["Если вместимости C хватает, любой большей тоже хватает", "Число дней всегда равно числу грузов", "Допустимость меняется с Yes на No и обратно при увеличении C"], 0, ["Старое распределение по дням остаётся возможным при большей вместимости.", "Допустимые вместимости образуют суффикс числового диапазона."], "У проверки есть одна граница перехода от недопустимых значений к допустимым; это и есть предмет поиска.")
            ], ["бинарный поиск", "lower_bound", "поиск по ответу"])
    ])]
    for item, minutes in zip(result[0]["lessons"], [30, 35, 35, 40]):
        item["minutes"] = minutes
    return result
